#define ALLOC_SIZE (500 * 1024 * 1024) // 500MB
#define ITERATIONS 100
#define CHILD_PATH "/bin/true"

// External variable for posix_spawn
extern char **environ;

static void benchmark_method(const char *method_name, 
                           void (*method)(int *), 
                           int *success_count) {
    struct timespec start, end;
    double total_time = 0.0;

    *success_count = 0;

    clock_gettime(CLOCK_MONOTONIC, &start);

    for (int i = 0; i < ITERATIONS; i++) {
        method(success_count);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    total_time = (end.tv_sec - start.tv_sec) + 
                 (double)(end.tv_nsec - start.tv_nsec) / 1000000000.0;

    double forks_per_sec = ITERATIONS / total_time;

    printf("%s: %.2f forks/sec (success: %d/%d)\n", 
           method_name, forks_per_sec, *success_count, ITERATIONS);
}

// Traditional fork + execve
void fork_execve_method(int *success_count) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        return;
    }

    if (pid == 0) { // Child
        execl(CHILD_PATH, "true", (char *)NULL);
        perror("execl");
        _exit(EXIT_FAILURE);
    } else { // Parent
        int status;
        if (waitpid(pid, &status, 0) == -1) {
            perror("waitpid");
            return;
        }
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            (*success_count)++;
        }
    }
}

