#include <iostream>
#include <fstream>
#include <string>
#include <sstream>

int main() {
    std::ifstream file("/app/task_file/input/file.txt");

    if (!file.is_open()) {
        std::cerr << "Error: Could not open the file." << std::endl;
        return 1;
    }

    std::string line;
    while (std::getline(file, line)) {
        if (line.empty()) continue;

        std::istringstream iss(line);
        int x, y;
        if (iss >> x >> y) {
            std::cout << "Coordinate: (" << x << ", " << y << ")" << std::endl;
        }
    }

    file.close();
    return 0;
}
